INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 29, 'theory', 'Квиз: Чтение большого проекта');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 0, 'Какой ключ git grep показывает не только строку с совпадением, но и всю функцию, в которой оно найдено?', '["-n", "-W", "--heading", "--and"]', 1, '-W (--function-context) показывает текст от строки с именем функции до следующей функции. -n лишь добавляет номера строк, --heading выносит имя файла в отдельную строку, а --and соединяет шаблоны.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 1, 'Что находит git log -S''kvm_cpu_exec''?', '["Все коммиты, в сообщении которых есть эта строка", "Все коммиты, которые трогали файл с таким именем", "Только коммиты, добавившие эту строку впервые", "Коммиты, изменившие число вхождений этой строки в файлах"]', 3, '-S ищет по содержимому изменений: коммит попадает в список, если число вхождений строки до и после него разное. Поэтому в списке будут и добавление, и удаление, и переименование. Поиск по сообщениям - это --grep.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 2, 'В отчёте perf report у функции Self равно 2%, а Children равно 80%. Что это значит?', '["Сама функция почти не тратит время, но через неё проходит 80% образцов: время уходит в вызываемые ею функции", "Функция вызывается в 2% случаев", "Образцы с этой функцией потеряны на 78%", "Функция занимает 2% кода программы"]', 0, 'Self - это время в самой функции, Children - время в ней и во всём, что она вызвала. Большой Children при малом Self указывает на вызываемые функции, их и надо читать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 3, 'В выводе ps -T для процесса QEMU вы видите поток с именем «CPU 1/KVM». Что это и что он, скорее всего, делает?', '["Поток ядра, который сохраняет состояние гостя на диск", "Поток монитора, который принимает команды QMP", "Поток виртуального процессора номер 1: он в цикле вызывает ioctl KVM_RUN", "Рабочий поток пула, который выполняет блокирующие задания"]', 2, 'QEMU называет поток виртуального процессора так в kvm_start_vcpu_thread, а выполняет он kvm_cpu_exec с ioctl KVM_RUN (QEMU 11.1). Монитор и рабочие потоки называются иначе: IO mon_iothread и worker.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 29, 4, 'В строке файла tags есть поле «file:» без значения. Что оно означает?', '["Символ определён в заголовочном файле", "Символ статический: он виден только в своём файле", "Файл с символом удалён из репозитория", "Адрес символа — номер строки, а не шаблон"]', 1, 'По описанию формата tags поле file: помечает статический (локальный) тег с областью видимости в одном файле; при пустом значении это файл самой строки. Так ctags отличает одноимённые static-функции разных файлов.');
